-- Django stores '' (and '{}' for ArrayField) for blank values. Give every remaining NOT NULL
-- text column the same default so hand-written INSERTs only list the columns they care about.
DO $$
DECLARE r record;
BEGIN
  FOR r IN SELECT table_name, column_name, data_type FROM information_schema.columns
           WHERE table_schema = 'public' AND is_nullable = 'NO' AND column_default IS NULL
             AND data_type IN ('text', 'character varying', 'ARRAY')
  LOOP
    EXECUTE format('ALTER TABLE public.%I ALTER COLUMN %I SET DEFAULT %s', r.table_name, r.column_name,
                   CASE WHEN r.data_type = 'ARRAY' THEN '''{}''' ELSE '''''' END);
  END LOOP;
END $$;
